async function transfer(db: SQLiteDatabase, from: number, to: number, amount: number) {
  await db.withTransactionAsync(async () => {
    await db.runAsync('UPDATE accounts SET balance = balance - ? WHERE id = ?', amount, from);
    await db.runAsync('UPDATE accounts SET balance = balance + ? WHERE id = ?', amount, to);
  });
}

