CREATE TABLE notes (
  id TEXT PRIMARY KEY NOT NULL,        -- client-generated UUID
  title TEXT NOT NULL,
  body TEXT NOT NULL DEFAULT '',
  updated_at INTEGER NOT NULL,         -- device time, display only
  server_version INTEGER,              -- NULL until first successful push
  deleted INTEGER NOT NULL DEFAULT 0   -- tombstone
);

CREATE TABLE outbox (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  op_id TEXT NOT NULL UNIQUE,          -- sent as the Idempotency-Key
  entity_id TEXT NOT NULL,
  op TEXT NOT NULL CHECK (op IN ('upsert', 'delete')),
  payload TEXT NOT NULL,               -- JSON
  base_version INTEGER,                -- server version the edit started from
  attempts INTEGER NOT NULL DEFAULT 0,
  parked INTEGER NOT NULL DEFAULT 0,   -- needs user attention (409 / validation error)
  last_error TEXT
);

CREATE TABLE sync_state (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL);

-- A local edit: row + outbox op in ONE transaction
BEGIN;
INSERT INTO notes (id, title, body, updated_at) VALUES (?, ?, ?, ?)
  ON CONFLICT (id) DO UPDATE SET
    title = excluded.title, body = excluded.body, updated_at = excluded.updated_at;
INSERT INTO outbox (op_id, entity_id, op, payload, base_version) VALUES (?, ?, 'upsert', ?, ?);
COMMIT;

-- Pull: apply a server row unless a local change is still pending
INSERT INTO notes (id, title, body, updated_at, server_version, deleted) VALUES (?, ?, ?, ?, ?, ?)
  ON CONFLICT (id) DO UPDATE SET
    title = excluded.title, body = excluded.body, updated_at = excluded.updated_at,
    server_version = excluded.server_version, deleted = excluded.deleted
  WHERE NOT EXISTS (SELECT 1 FROM outbox WHERE outbox.entity_id = excluded.id);

