import type { SQLiteDatabase } from 'expo-sqlite';

type OutboxRow = {
  seq: number; op_id: string; entity_id: string;
  op: 'upsert' | 'delete'; payload: string; base_version: number | null;
};

let pushing = false;

export async function pushOutbox(
  db: SQLiteDatabase,
  send: (row: OutboxRow) => Promise<Response>, // sets Idempotency-Key: row.op_id
): Promise<'done' | 'offline' | 'retry-later'> {
  if (pushing) return 'done'; // one push loop at a time keeps ops in order
  pushing = true;
  try {
    const rows = await db.getAllAsync<OutboxRow>(
      `SELECT seq, op_id, entity_id, op, payload, base_version
         FROM outbox WHERE parked = 0 ORDER BY seq LIMIT 50`,
    );
    for (const row of rows) {
      let res: Response;
      try {
        res = await send(row);
      } catch {
        return 'offline'; // keep the op; try again on reconnect
      }
      if (res.ok) {
        const { serverVersion } = await res.json();
        await db.withTransactionAsync(async () => {
          await db.runAsync('UPDATE notes SET server_version = ? WHERE id = ?', serverVersion, row.entity_id);
          await db.runAsync('DELETE FROM outbox WHERE seq = ?', row.seq);
        });
      } else if (res.status === 429 || res.status >= 500) {
        await db.runAsync(
          'UPDATE outbox SET attempts = attempts + 1, last_error = ? WHERE seq = ?',
          `HTTP ${res.status}`, row.seq,
        );
        return 'retry-later'; // back off, keep the order
      } else {
        // 409 conflict or validation error: park it, show it in the UI, don't block the queue
        await db.runAsync('UPDATE outbox SET parked = 1, last_error = ? WHERE seq = ?', `HTTP ${res.status}`, row.seq);
      }
    }
    return 'done';
  } finally {
    pushing = false;
  }
}

