// Client state shared by many screens: Zustand
import { create } from 'zustand';

type CartState = {
  items: Record<string, number>;
  add: (productId: string) => void;
  clear: () => void;
};

export const useCart = create<CartState>()((set) => ({
  items: {},
  add: (id) => set((s) => ({ items: { ...s.items, [id]: (s.items[id] ?? 0) + 1 } })),
  clear: () => set({ items: {} }),
}));

// Server state: TanStack Query
import { useQuery } from '@tanstack/react-query';

type Product = { id: string; name: string; price: number };

export function useProducts() {
  return useQuery({
    queryKey: ['products'],
    queryFn: async (): Promise<Product[]> => {
      const res = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/products`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    },
    staleTime: 60_000,
  });
}

// A row subscribes only to its own quantity
function CartBadge({ productId }: { productId: string }) {
  const qty = useCart((s) => s.items[productId] ?? 0);
  return qty > 0 ? <Text>{qty}</Text> : null;
}

export class HttpError extends Error {
  status: number;
  constructor(status: number) {
    super(`HTTP ${status}`);
    this.status = status;
  }
}

const RETRYABLE_STATUS = new Set([408, 429, 500, 502, 503, 504]);
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export async function fetchWithTimeout(url: string, init: RequestInit = {}, timeoutMs = 10_000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, { ...init, signal: controller.signal });
    if (!res.ok) throw new HttpError(res.status);
    return res;
  } finally {
    clearTimeout(timer);
  }
}

// Only for idempotent requests (GET, PUT, or POST with an Idempotency-Key)
export async function fetchWithRetry(
  url: string,
  init: RequestInit = {},
  { retries = 3, baseDelayMs = 500, timeoutMs = 10_000 } = {},
) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await fetchWithTimeout(url, init, timeoutMs);
    } catch (err) {
      const retryable = !(err instanceof HttpError) || RETRYABLE_STATUS.has(err.status);
      if (!retryable || attempt >= retries) throw err;
      await sleep(Math.random() * baseDelayMs * 2 ** attempt); // exponential backoff, full jitter
    }
  }
}

