import * as SecureStore from 'expo-secure-store';

const API_URL = process.env.EXPO_PUBLIC_API_URL; // public on purpose: a URL is not a secret
const REFRESH_KEY = 'auth.refreshToken';

let accessToken: string | null = null; // short-lived, memory only
let refreshing: Promise<string> | null = null;

type Session = { accessToken: string; refreshToken: string };

export async function saveSession(s: Session) {
  accessToken = s.accessToken;
  await SecureStore.setItemAsync(REFRESH_KEY, s.refreshToken, {
    keychainAccessible: SecureStore.AFTER_FIRST_UNLOCK,
  });
}

export async function signOut() {
  accessToken = null;
  await SecureStore.deleteItemAsync(REFRESH_KEY);
}

function refreshAccessToken(): Promise<string> {
  // single-flight: ten parallel 401s share ONE refresh call
  refreshing ??= (async () => {
    try {
      const refreshToken = await SecureStore.getItemAsync(REFRESH_KEY);
      if (!refreshToken) throw new Error('Not signed in');
      const res = await fetch(`${API_URL}/auth/refresh`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken }),
      });
      if (!res.ok) {
        await signOut(); // refresh token expired or revoked
        throw new Error('Session expired');
      }
      const session: Session = await res.json(); // server rotates the refresh token
      await saveSession(session);
      return session.accessToken;
    } finally {
      refreshing = null;
    }
  })();
  return refreshing;
}

export async function authFetch(
  path: string,
  init: Omit<RequestInit, 'headers'> & { headers?: Record<string, string> } = {},
) {
  const send = (token: string) =>
    fetch(`${API_URL}${path}`, { ...init, headers: { ...init.headers, Authorization: `Bearer ${token}` } });

  let res = await send(accessToken ?? (await refreshAccessToken()));
  if (res.status === 401) res = await send(await refreshAccessToken());
  return res;
}

