import type { SQLiteDatabase } from 'expo-sqlite';

type Message = { id: number; sender: string; body: string; created_at: number };
type Cursor = { createdAt: number; id: number } | null;

export async function loadMessages(db: SQLiteDatabase, chatId: number, cursor: Cursor, pageSize = 50) {
  const rows = cursor
    ? await db.getAllAsync<Message>(
        `SELECT id, sender, body, created_at FROM messages
          WHERE chat_id = ? AND (created_at, id) < (?, ?)
          ORDER BY created_at DESC, id DESC LIMIT ?`,
        chatId, cursor.createdAt, cursor.id, pageSize,
      )
    : await db.getAllAsync<Message>(
        `SELECT id, sender, body, created_at FROM messages
          WHERE chat_id = ?
          ORDER BY created_at DESC, id DESC LIMIT ?`,
        chatId, pageSize,
      );
  const last = rows.at(-1);
  return { rows, next: last ? { createdAt: last.created_at, id: last.id } : null };
}

// Export a whole chat without holding every row in memory
export async function exportChat(db: SQLiteDatabase, chatId: number, write: (line: string) => Promise<void>) {
  for await (const m of db.getEachAsync<Message>(
    'SELECT id, sender, body, created_at FROM messages WHERE chat_id = ? ORDER BY created_at, id',
    chatId,
  )) {
    await write(`${new Date(m.created_at).toISOString()} ${m.sender}: ${m.body}\n`);
  }
}

